schema.schemaSDL:
type Query {
  product(id: ID!): Product
  products: [Product]
}

type Mutation {
  submitOrder(productId: ID!, quantity: Int!, shippingAddress: AddressInput!): OrderConfirmation
}

type Product {
  id: ID!
  name: String!
  price: Float!
  availability: Int!
}

input AddressInput {
  street: String!
  city: String!
  postalCode: String!
  country: String!
}

type OrderConfirmation {
  orderId: ID!
  estimatedDelivery: String!
}

mutations.mutation:
mutation {
  submitOrder(
    productId: "1", 
    quantity: 2, 
    shippingAddress: {
      street: "123 Main St",
      city: "Anytown",
      postalCode: "12345",
      country: "USA"
    }
  ) {
    orderId
    estimatedDelivery
  }
}
